import Foundation

/// Hand-written lessons come from the bundle; the rest are generated by AI once and cached on disk.
final class LessonRepository: ObservableObject {
    static let shared = LessonRepository()

    @Published private(set) var generated: [String: Lesson] = [:]
    private let directory: URL

    private init() {
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        directory = docs.appendingPathComponent("lessons", isDirectory: true)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

        var loaded: [String: Lesson] = [:]
        let files = (try? FileManager.default.contentsOfDirectory(at: directory, includingPropertiesForKeys: nil)) ?? []
        for file in files where file.pathExtension == "json" {
            if let data = try? Data(contentsOf: file),
               let lesson = try? JSONDecoder().decode(Lesson.self, from: data) {
                loaded[lesson.id] = lesson
            }
        }
        generated = loaded
        ItemIndex.shared.register(loaded.values.flatMap { $0.items })
    }

    func lesson(for entry: LessonEntry) -> Lesson? {
        entry.bundled ?? generated[entry.id]
    }

    func isReady(_ entry: LessonEntry) -> Bool { lesson(for: entry) != nil }

    var generatedCount: Int { generated.count }

    func discard(_ entry: LessonEntry) {
        guard entry.bundled == nil else { return }
        try? FileManager.default.removeItem(at: fileURL(entry.id))
        generated[entry.id] = nil
    }

    func discardAll() {
        for id in generated.keys { try? FileManager.default.removeItem(at: fileURL(id)) }
        generated = [:]
    }

    private func fileURL(_ id: String) -> URL { directory.appendingPathComponent(id + ".json") }

    // MARK: Generation

    func generate(_ entry: LessonEntry) async throws -> Lesson {
        if let ready = lesson(for: entry) { return ready }
        guard let spec = entry.spec else { throw AIError.emptyResponse }

        let level = entry.levelId
        let previous = CourseStore.shared.lessonsInOrder
            .filter { $0.levelId == level }
            .prefix(while: { $0.id != entry.id })
            .map { $0.title }
        let system = Prompts.lessonSystem(level: level) + "\n\n" + Prompts.jsonRule
        let prompt = Prompts.lessonPrompt(spec: spec, level: level, unitTitle: entry.unitTitle,
                                          previousTitles: Array(previous))

        var lastError: Error = AIError.emptyResponse
        for _ in 0..<2 {
            do {
                let raw = try await AIClient.shared.complete(system: system,
                                                             messages: [AIMessage(role: .user, content: prompt)],
                                                             maxTokens: 12000)
                let lesson = try Self.buildLesson(from: raw, spec: spec)
                let data = try Self.encodeLessonJSON(raw: raw, spec: spec)
                try? data.write(to: fileURL(entry.id), options: .atomic)
                ItemIndex.shared.register(lesson.items)
                await MainActor.run { self.generated[entry.id] = lesson }
                return lesson
            } catch let error as AIError {
                // Network / key errors won't fix themselves by retrying.
                if case .invalidJSON = error { lastError = error; continue }
                throw error
            } catch {
                lastError = AIError.invalidJSON(String(describing: error))
            }
        }
        throw lastError
    }

    // MARK: Cleaning up AI output

    static func buildLesson(from raw: String, spec: LessonSpec) throws -> Lesson {
        let data = try encodeLessonJSON(raw: raw, spec: spec)
        do {
            return try JSONDecoder().decode(Lesson.self, from: data)
        } catch {
            throw AIError.invalidJSON(String(describing: error))
        }
    }

    /// Validates and repairs the model's JSON so it always decodes into a usable lesson.
    static func encodeLessonJSON(raw: String, spec: LessonSpec) throws -> Data {
        guard let object = try? JSONSerialization.jsonObject(with: AIClient.extractJSON(raw)),
              let dict = object as? [String: Any] else {
            throw AIError.invalidJSON("无法解析 JSON")
        }

        // Tips
        let tips: [[String: String]] = (dict["tips"] as? [[String: Any]] ?? []).compactMap { t in
            guard let title = str(t["title"]), let body = str(t["body"]) else { return nil }
            return ["title": title, "body": body]
        }

        // Items
        var seenEs = Set<String>(), seenZh = Set<String>()
        var items: [[String: String]] = []
        for raw in dict["items"] as? [[String: Any]] ?? [] {
            guard let es = str(raw["es"]), let zh = str(raw["zh"]),
                  !seenEs.contains(es), !seenZh.contains(zh) else { continue }
            seenEs.insert(es); seenZh.insert(zh)
            var item: [String: String] = ["id": String(format: "%@-%02d", spec.id, items.count + 1), "es": es, "zh": zh]
            if let note = str(raw["note"]) { item["note"] = note }
            if let pron = str(raw["pron"]) { item["pron"] = pron }
            items.append(item)
        }
        guard items.count >= 5 else { throw AIError.invalidJSON("词句太少（\(items.count)）") }

        // Exercises
        var exercises: [[String: Any]] = []
        for ex in dict["exercises"] as? [[String: Any]] ?? [] {
            switch str(ex["type"]) ?? "" {
            case "fill":
                guard var sentence = str(ex["sentence"]) else { continue }
                sentence = sentence.replacingOccurrences(of: "_{2,}", with: "___", options: .regularExpression)
                guard sentence.components(separatedBy: "___").count == 2 else { continue }
                let options = uniqueStrings(ex["options"])
                guard options.count >= 2 else { continue }
                var answer = str(ex["answer"])
                if answer == nil, let i = ex["answer"] as? Int, options.indices.contains(i) { answer = options[i] }
                guard let a = answer, options.contains(a) else { continue }
                var out: [String: Any] = ["type": "fill", "sentence": sentence, "zh": str(ex["zh"]) ?? "",
                                          "options": options, "answer": a]
                if let e = str(ex["explain"]) { out["explain"] = e }
                exercises.append(out)

            case "build":
                guard let full = str(ex["full"]) else { continue }
                let tokens = AnswerChecker.tokens(full)
                guard (2...14).contains(tokens.count) else { continue }
                let lower = Set(tokens.map { $0.lowercased() })
                let distractors = uniqueStrings(ex["distractors"]).filter { !lower.contains($0.lowercased()) }
                exercises.append(["type": "build", "prompt": str(ex["prompt"]) ?? "", "full": full,
                                  "answer": tokens, "distractors": Array(distractors.prefix(3))])

            case "type":
                guard let prompt = str(ex["prompt"]) else { continue }
                var answers = uniqueStrings(ex["answers"])
                let display = str(ex["display"]) ?? answers.first
                if let d = display { answers.append(d) }
                answers = answers.filter { !$0.isEmpty }
                guard !answers.isEmpty, let shown = display else { continue }
                var out: [String: Any] = ["type": "type", "prompt": prompt, "answers": answers, "display": shown]
                if let h = str(ex["hint"]) { out["hint"] = h }
                exercises.append(out)

            case "choice":
                guard let question = str(ex["question"]) else { continue }
                let options = uniqueStrings(ex["options"])
                guard options.count >= 2 else { continue }
                var index = ex["answer"] as? Int
                if index == nil, let s = str(ex["answer"]) { index = options.firstIndex(of: s) ?? Int(s) }
                guard let i = index, options.indices.contains(i) else { continue }
                var out: [String: Any] = ["type": "choice", "question": question, "options": options, "answer": i]
                if let e = str(ex["explain"]) { out["explain"] = e }
                if let sub = str(ex["sub"]) { out["sub"] = sub }
                if let so = ex["spanishOptions"] as? Bool { out["spanishOptions"] = so }
                exercises.append(out)

            default:
                continue
            }
        }

        let lesson: [String: Any] = [
            "id": spec.id, "title": spec.title, "subtitle": spec.subtitle, "icon": spec.icon,
            "tips": tips, "items": items, "exercises": exercises
        ]
        return try JSONSerialization.data(withJSONObject: lesson, options: [.prettyPrinted])
    }

    private static func str(_ value: Any?) -> String? {
        guard let s = value as? String else { return nil }
        let t = s.trimmingCharacters(in: .whitespacesAndNewlines)
        return t.isEmpty ? nil : t
    }

    private static func uniqueStrings(_ value: Any?) -> [String] {
        var out: [String] = []
        for v in value as? [Any] ?? [] {
            let s: String?
            if let text = v as? String { s = text } else if let n = v as? NSNumber { s = n.stringValue } else { s = nil }
            if let t = s?.trimmingCharacters(in: .whitespacesAndNewlines), !t.isEmpty, !out.contains(t) {
                out.append(t)
            }
        }
        return out
    }
}
